using System;using System.IO;using System.Linq;using System.Reflection;using System.Drawing;using System.Windows.Forms;using System.Web.Script.Serialization;
class SanctuaryChecks{static void Check(bool b,string m){if(!b)throw new Exception(m);}[STAThread]static void Main(){var f=BindingFlags.Instance|BindingFlags.NonPublic;var c=new JavaScriptSerializer().Deserialize<Chapter>(File.ReadAllText("D:/WORK/Cet6Story/chapters/10-tavern-prologue.json"));Check(c.lines.Take(12).Where(l=>l.speaker=="伊瑟雅").All(l=>l.actor=="iserya"),"goddess binding");Check(c.lines.Take(12).Where(l=>l.speaker=="陆川").All(l=>l.actor=="luchuan"),"hero binding");using(var portrait=new Bitmap("D:/WORK/Cet6Story/chapters/art/tavern/iserya-portrait.png"))Check(portrait.GetPixel(0,0).A==0,"transparent portrait");using(var g=new Game()){g.Show();typeof(Game).GetField("current",f).SetValue(g,c);var save=(Save)typeof(Game).GetField("save",f).GetValue(g);save.sectionAttempts[c.id]=new SectionAttempt{review=true,introShown=true};StoryRoutes.Flag(save,TavernStory.OpeningFlag);typeof(Game).GetField("index",f).SetValue(g,0);typeof(Game).GetMethod("ShowStory",f).Invoke(g,null);Application.DoEvents();var stage=(ArtPanel)typeof(Game).GetField("stage",f).GetValue(g);Check(stage.Actors.Count(a=>a.Visible)==2&&stage.Actors.Any(a=>a.Id=="iserya"&&a.Visible)&&stage.Actors.Any(a=>a.Id=="luchuan"&&a.Visible),"both portraits visible");using(var b=new Bitmap(stage.Width,stage.Height)){stage.DrawToBitmap(b,new Rectangle(Point.Empty,stage.Size));b.Save("D:/WORK/Cet6Story/.validation/sanctuary-dialogue-preview.png");}typeof(Game).GetField("index",f).SetValue(g,12);typeof(Game).GetMethod("UpdateLine",f).Invoke(g,null);Check(!stage.Actors.First(a=>a.Id=="iserya").Visible,"goddess hides after departure");}using(var canvas=new OpeningCgCanvas("","","",18)){bool completed=false;canvas.Completed=()=>completed=true;typeof(OpeningCgCanvas).GetMethod("PlaybackEnded",f).Invoke(canvas,null);Check(canvas.AwaitingContinue&&!completed,"CG waits for click");typeof(OpeningCgCanvas).GetMethod("ContinueAfterPlayback",f).Invoke(canvas,null);Check(completed,"click continues");}Console.WriteLine("PASS portrait bindings, transparency, sanctuary visibility, departure and CG click gate");}}
